/**
 * 🎵 01_アプリ連携メタデータ確定 & LRCLIB生成.js
 */
let input = $input.first()?.json || {};
if (input.body) input = input.body;
if (Array.isArray(input)) input = input[0] || {};
if (typeof input === 'string') {
  try {
    input = JSON.parse(input.trim());
    if (Array.isArray(input)) input = input[0] || {};
  } catch (e) {}
}

const rawTrackId = input.track_id || input.id || "";
let trackId = String(rawTrackId).trim();
const numMatch = trackId.match(/\d+/);
if (numMatch) trackId = numMatch[0];

if (!trackId) {
  throw new Error("⚠️ トラックID（track_id または id）が見つかりません。アプリの送信データをご確認ください。");
}

const trackTitle = String(input.title || input.track_name || input.name || "").trim();
const artistName = String(input.artist || input.artist_name || "").trim();
const albumName = String(input.album || input.album_name || "").trim();
const releaseDate = String(input.release_date || "").split('T')[0];
const previewUrl = String(input.preview_url || "").trim();
const trackViewUrl = String(input.track_view_url || input.itunes_url || "").trim();

let coverUrl = String(input.artwork_url || input.album_cover || "").trim();
if (coverUrl) {
  coverUrl = coverUrl.replace(/\/\d+x\d+bb\./, '/600x600bb.');
}

let youtubeId = "";
const rawYt = input.youtube_id || input.youtube || input.youtube_url || input.mv_url || "";
if (rawYt) {
  const ytMatch = String(rawYt).match(/(?:v=|\/|youtu\.be\/)([a-zA-Z0-9_-]{11})/);
  if (ytMatch) {
    youtubeId = ytMatch[1];
  } else if (/^[a-zA-Z0-9_-]{11}$/.test(String(rawYt).trim())) {
    youtubeId = String(rawYt).trim();
  }
}

const wikidataId = String(input.wikidata_id || input.wiki_data_id || "").trim();
const isrc = String(input.isrc || "").trim();
const musicbrainzId = String(input.musicbrainz_id || "").trim();
const releaseYear = String(input.year || releaseDate.split('-')[0] || "").trim();

let queryForLyrics = "";
if (trackTitle && artistName) {
  queryForLyrics = `${trackTitle} ${artistName}`;
} else {
  queryForLyrics = trackTitle || artistName || input.query || "";
}

const cleanQuery = queryForLyrics.replace(/[()[\]{}「」『』]/g, ' ').replace(/\s+/g, ' ').trim();
const lrclibUrl = `https://lrclib.net/api/search?q=${encodeURIComponent(cleanQuery)}`;

return [{
  json: {
    track_meta: {
      track_id: trackId,
      track_name: trackTitle,
      track_name_en: trackTitle,
      artist_name: artistName,
      artist_name_en: artistName,
      album_name: albumName,
      album_cover: coverUrl,
      preview_url: previewUrl,
      itunes_url: trackViewUrl,
      youtube_id: youtubeId,
      wikidata_id: wikidataId || null,
      isrc: isrc || null,
      musicbrainz_id: musicbrainzId || null,
      release_date: releaseDate,
      release_year: releaseYear || null,
      genre: input.genre || 'K-POP',
      query: input.query || ""
    },
    lrclib_search_url: lrclibUrl,
    model: 'gemini-3.8-flash',
    source: 'music_search_app'
  }
}];

/**
 * 🎵 03_Geminiリクエスト生成_メタデータ完全保持版.js
 */
let input = $input.first()?.json || {};

let trackMeta = input.track_meta;
if (!trackMeta || !trackMeta.track_id) {
  try {
    trackMeta = $('01_アプリ連携メタデータ確定 & LRCLIB生成')?.first()?.json?.track_meta || {};
  } catch (e) {
    trackMeta = {};
  }
}

if (!trackMeta.track_id) {
  try {
    const rawWebhook = $('Webhook (アプリ検索結果受信)')?.first()?.json || {};
    const item = rawWebhook.body || rawWebhook;
    const target = Array.isArray(item) ? item[0] : item;
    if (target && (target.track_id || target.id)) {
      trackMeta = {
        track_id: String(target.track_id || target.id),
        track_name: target.title || target.track_name || "",
        track_name_en: target.title || target.track_name || "",
        artist_name: target.artist || target.artist_name || "",
        artist_name_en: target.artist || target.artist_name || "",
        album_name: target.album || "",
        album_cover: (target.artwork_url || "").replace(/\/\d+x\d+bb\./, '/600x600bb.'),
        preview_url: target.preview_url || "",
        itunes_url: target.track_view_url || target.itunes_url || "",
        youtube_id: target.youtube_id || "",
        wikidata_id: target.wikidata_id || target.wiki_data_id || null,
        isrc: target.isrc || null,
        musicbrainz_id: target.musicbrainz_id || null,
        release_date: (target.release_date || "").split('T')[0],
        release_year: target.year || (target.release_date ? target.release_date.split('-')[0] : null),
        genre: target.genre || 'K-POP'
      };
    }
  } catch (e) {}
}

let autoLyrics = "";
let lrcList = [];
if (Array.isArray(input)) {
  lrcList = input;
} else if (input.data && Array.isArray(input.data)) {
  lrcList = input.data;
} else if (Array.isArray($input.all())) {
  lrcList = $input.all().map(i => i.json);
}

const matchedLrc = lrcList.find(item => item && item.plainLyrics && item.plainLyrics.trim().length > 0) || lrcList[0];
if (matchedLrc && matchedLrc.plainLyrics) {
  autoLyrics = matchedLrc.plainLyrics.trim();
}

const trackName = trackMeta.track_name || "";
const artistName = trackMeta.artist_name || "";
const albumName = trackMeta.album_name || "";
const genre = trackMeta.genre || "K-POP";
const releaseDate = trackMeta.release_date || "";

let customLyrics = "";
try {
  customLyrics = input.custom_lyrics || $('Webhook (アプリ検索結果受信)')?.first()?.json?.custom_lyrics || "";
} catch (e) {}

let officialLyrics = "";
if (customLyrics && customLyrics.trim().length > 0) {
  officialLyrics = customLyrics.trim();
} else if (autoLyrics && autoLyrics.trim().length > 0) {
  officialLyrics = autoLyrics.trim();
}

const hasOfficialLyrics = (officialLyrics && officialLyrics.trim().length > 0);

const systemInstruction = `あなたは韓国語教育の最高峰エキスパートであり、K-POP・韓国ドラマOSTの歌詞対訳プロフェッショナルです。\n韓国語学習アプリ「K-Learner」に格納する、超高品質な「公式歌詞・対訳・語彙・文法」JSONデータを生成してください。\n\n【⚠️ 最重要：公式歌詞の完全性・正確性】\n- 本データは【個人利用の語学学習用】です。要約や省略は一切禁止です。\n${hasOfficialLyrics ? '- 提供された「公式フル歌詞」を一言一句完全に一致させて出力してください。\n- イントロ、サビ、アウトロまで、公式音源の歌唱順通りにすべてのフレーズを完全収録してください。' : '- 韓国の公式音源サイト（Melon, Genie, Bugs等）に登録されている公式歌詞を正確に特定し、1行も省略せず完全収録してください。'}\n\n【出力フォーマット】\nMarkdown装飾（\\`\\`\\`json）を含めず、必ず完全な純粋JSONオブジェクトのみを返してください。\n{\n  \"title_ko\": \"曲名（韓国語ハングル）\",\n  \"title_ja\": \"曲名（日本語・英語副題）\",\n  \"artist\": \"アーティスト名\",\n  \"category\": \"ジャンル・作品名\",\n  \"level\": \"学習目安レベル\",\n  \"sentences\": [ { \"ko\": \"...\", \"rubi\": \"...\", \"ja\": \"...\" } ],\n  \"vocab\": [ { \"word\": \"...\", \"hanja\": \"...\", \"pos\": \"...\", \"meaning\": \"...\", \"level\": \"...\" } ],\n  \"grammar\": [ { \"pattern\": \"...\", \"meaning\": \"...\", \"desc\": \"...\" } ],\n  \"lyrics_notes\": [ \"💬 <strong>...:</strong> ...\" ]\n}`;

let userPrompt = `対象楽曲情報:\n- 曲名: ${trackName}\n- アーティスト: ${artistName}\n- アルバム: ${albumName}\n- ジャンル: ${genre}\n- リリース日: ${releaseDate}`;\n\nif (hasOfficialLyrics) {\n  userPrompt += `\\n\\n【公式フル歌詞テキスト（これを100%忠実に使用してください）】:\\n${officialLyrics}\\n\\n⚠️ 最重要注意事項：上記の公式歌詞を一言一句漏らさず全てsentencesに分解し、対訳・ルビ・語彙・文法を付与して出力してください。AIによる勝手な作詞や言い換え、行の削除・省略は絶対に禁止です。`;\n} else {\n  userPrompt += `\\n\\n⚠️ 歌詞APIサーバー混雑のため、あなたの膨大な韓国音楽ナレッジベースから該当楽曲の「韓国語公式フル歌詞」を正確に特定し、1行も省略せず全フレーズをsentencesに分解して、対訳・ルビ・語彙・文法を出力してください。`;\n}\n\nconst selectedModel = 'gemini-3.8-flash';\n\nreturn [{\n  json: {\n    model: selectedModel,\n    track_meta: trackMeta,\n    gemini_request: {\n      contents: [
        {
          role: "user",
          parts: [{ text: systemInstruction + "\n\n" + userPrompt }]
        }
      ],
      generationConfig: {
        temperature: 0.0,
        response_mime_type: "application/json"
      }
    }
  }
}];

/**
 * 🎵 05_Supabase整形 & コスト算出.js
 */
const geminiResponse = $input.first()?.json || {};

let trackMeta = {};
try {
  trackMeta = $('03_Gemini 教材生成プロンプト構築')?.first()?.json?.track_meta || {};
} catch (e) {}

if (!trackMeta.track_id || !trackMeta.preview_url) {
  try {
    const meta01 = $('01_アプリ連携メタデータ確定 & LRCLIB生成')?.first()?.json?.track_meta || {};
    trackMeta = { ...meta01, ...trackMeta };
  } catch (e) {}
}

if (!trackMeta.track_id || !trackMeta.preview_url) {
  try {
    const webhookData = $('Webhook (アプリ検索結果受信)')?.first()?.json || {};
    const item = webhookData.body || webhookData;
    const target = Array.isArray(item) ? item[0] : item;
    if (target && (target.track_id || target.id)) {
      trackMeta = {
        track_id: String(target.track_id || target.id),
        track_name: target.title || target.track_name || trackMeta.track_name || "",
        track_name_en: target.title || target.track_name || trackMeta.track_name_en || "",
        artist_name: target.artist || target.artist_name || trackMeta.artist_name || "",
        artist_name_en: target.artist || target.artist_name || trackMeta.artist_name_en || "",
        album_name: target.album || trackMeta.album_name || "",
        album_cover: (target.artwork_url || "").replace(/\/\d+x\d+bb\./, '/600x600bb.') || trackMeta.album_cover || "",
        preview_url: target.preview_url || trackMeta.preview_url || "",
        itunes_url: target.track_view_url || target.itunes_url || trackMeta.itunes_url || "",
        youtube_id: target.youtube_id || trackMeta.youtube_id || "",
        wikidata_id: target.wikidata_id || target.wiki_data_id || trackMeta.wikidata_id || null,
        isrc: target.isrc || trackMeta.isrc || null,
        musicbrainz_id: target.musicbrainz_id || trackMeta.musicbrainz_id || null,
        release_date: (target.release_date || "").split('T')[0] || trackMeta.release_date || "",
        release_year: target.year || trackMeta.release_year || null,
        genre: target.genre || trackMeta.genre || 'K-POP'
      };
    }
  } catch (e) {}
}

let responseText = "";
let promptTokens = 0;
let completionTokens = 0;
let totalTokens = 0;

if (geminiResponse.candidates && geminiResponse.candidates[0]?.content?.parts) {
  responseText = geminiResponse.candidates[0].content.parts.map(p => p.text).join("\n");
  if (geminiResponse.usageMetadata) {
    promptTokens = geminiResponse.usageMetadata.promptTokenCount || 0;
    completionTokens = geminiResponse.usageMetadata.candidatesTokenCount || 0;
    totalTokens = geminiResponse.usageMetadata.totalTokenCount || (promptTokens + completionTokens);
  }
} else {
  responseText = typeof geminiResponse === 'string' ? geminiResponse : JSON.stringify(geminiResponse);
}

const USD_TO_JPY = 155.0;
const MODEL_NAME = (trackMeta.model || "gemini-3.8-flash").toLowerCase();
let rates = { input: 0.100, output: 0.400 };
if (MODEL_NAME.includes("pro")) rates = { input: 1.250, output: 5.000 };
else if (MODEL_NAME.includes("lite")) rates = { input: 0.0375, output: 0.150 };

const costUsdInput = (promptTokens / 1000000) * rates.input;
const costUsdOutput = (completionTokens / 1000000) * rates.output;
const totalCostUsd = costUsdInput + costUsdOutput;
const totalCostJpy = totalCostUsd * USD_TO_JPY;
const formattedJpy = totalCostJpy < 0.01 ? `${(totalCostJpy * 100).toFixed(2)} 銭` : `${totalCostJpy.toFixed(3)} 円`;
const formattedUsd = `$${totalCostUsd.toFixed(6)}`;

let lyricsData = {};
try {
  let cleanJsonStr = responseText.trim();
  cleanJsonStr = cleanJsonStr.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
  lyricsData = JSON.parse(cleanJsonStr);
} catch (err) {
  lyricsData = { title_ko: trackMeta.track_name || "", sentences: [], vocab: [], grammar: [], lyrics_notes: [] };
}

const trackId = String(trackMeta.track_id || "");
const finalLyricsPayload = {
  id: `lyrics-${trackId}`,
  title_ko: lyricsData.title_ko || trackMeta.track_name || "無題",
  title_ja: lyricsData.title_ja || trackMeta.track_name || "無題",
  artist: trackMeta.artist_name || lyricsData.artist || "アーティスト不明",
  category: lyricsData.category || "K-POP / OST",
  level: lyricsData.level || "日常会話・感情表現",
  cat_class: "cat-music",
  source: trackMeta.album_name ? `Album『${trackMeta.album_name}』` : "Apple Music / 公式音源",
  preview_url: trackMeta.preview_url || null,
  itunes_url: trackMeta.itunes_url || null,
  album_cover: trackMeta.album_cover || null,
  youtube_id: trackMeta.youtube_id || null,
  wikidata_id: trackMeta.wikidata_id || null,
  isrc: trackMeta.isrc || null,
  musicbrainz_id: trackMeta.musicbrainz_id || null,
  release_year: trackMeta.release_year || null,
  mv_url: trackMeta.youtube_id ? `https://www.youtube.com/watch?v=${trackMeta.youtube_id}` : null,
  mv_embed_url: trackMeta.youtube_id ? `https://www.youtube-nocookie.com/embed/${trackMeta.youtube_id}` : null,
  sentences: Array.isArray(lyricsData.sentences) ? lyricsData.sentences : [],
  vocab: Array.isArray(lyricsData.vocab) ? lyricsData.vocab : [],
  grammar: Array.isArray(lyricsData.grammar) ? lyricsData.grammar : [],
  lyrics_notes: Array.isArray(lyricsData.lyrics_notes) ? lyricsData.lyrics_notes : [],
  generation_cost: {
    model: MODEL_NAME,
    prompt_tokens: promptTokens,
    completion_tokens: completionTokens,
    total_tokens: totalTokens,
    cost_usd: formattedUsd,
    cost_jpy: formattedJpy,
    generated_at: new Date().toISOString()
  }
};

const supabaseRecord = {
  track_id: trackId,
  track_name: finalLyricsPayload.title_ja,
  track_name_en: finalLyricsPayload.title_ko,
  artist_name: trackMeta.artist_name || finalLyricsPayload.artist,
  artist_name_en: trackMeta.artist_name_en || trackMeta.artist_name,
  country: "KR",
  genre: trackMeta.genre || "Ballad",
  preview_url: finalLyricsPayload.preview_url,
  itunes_url: finalLyricsPayload.itunes_url,
  album_cover: finalLyricsPayload.album_cover,
  youtube_id: trackMeta.youtube_id || null,
  mv_url: finalLyricsPayload.mv_url,
  release_year: trackMeta.release_year || null,
  wikidata_id: trackMeta.wikidata_id || null,
  isrc: trackMeta.isrc || null,
  musicbrainz_id: trackMeta.musicbrainz_id || null,
  description: finalLyricsPayload.title_ja,
  lyrics: JSON.stringify(finalLyricsPayload)
};

return [{ json: supabaseRecord }];
